"""Conversation history persistence for Copilot v2.

Hosts the ``ThreadStore`` protocol plus an in-memory implementation (tests) and
a SQLite-backed implementation (production). Each stored record follows the
AG-UI Message shape and is keyed by ``thread_id``, so a turn can be rehydrated
verbatim from what was streamed to the client.

The SQLite store writes to the same database file as the v1 history store but in
its own ``thread_messages`` table, next to a ``copilot_threads`` table holding
per-thread metadata (owner, title, timestamps). WAL mode plus conservative
pragmas let the v1 and v2 writers share the file without tripping over each
other's locks.
"""

from __future__ import annotations

import asyncio
import json
import os
import sqlite3
import uuid
from collections import defaultdict
from contextlib import contextmanager
from datetime import datetime, timezone
from typing import (
    Any,
    Callable,
    Generator,
    Optional,
    Protocol,
    TypeVar,
    runtime_checkable,
)

from pydantic import BaseModel, ConfigDict

_T = TypeVar("_T")

_TITLE_MAX_CHARS = 60
_TITLE_ELLIPSIS = "..."


class ThreadInfo(BaseModel):
    """Metadata of one conversation thread.

    Every thread belongs to exactly one user. ``title`` stays ``None`` until the
    first user message arrives.
    """

    model_config = ConfigDict(frozen=True)

    id: str
    user_id: str
    title: Optional[str]
    created_at: float
    updated_at: float


def can_use_thread(thread: ThreadInfo, caller_user_id: str) -> bool:
    """Return whether the caller may read or run the thread: only its owner may."""
    return thread.user_id == caller_user_id


def _now() -> float:
    """Return the current time in the same unit as ``thread_messages.created_at``."""
    return datetime.now(timezone.utc).timestamp()


def title_from_text(text: str) -> Optional[str]:
    """Derive a thread title from the first user message.

    Whitespace is collapsed and the result truncated to ``_TITLE_MAX_CHARS``
    characters, with an ellipsis appended when anything was cut. Returns
    ``None`` for blank text.
    """
    collapsed = " ".join(text.split())
    if not collapsed:
        return None
    if len(collapsed) <= _TITLE_MAX_CHARS:
        return collapsed
    return collapsed[:_TITLE_MAX_CHARS] + _TITLE_ELLIPSIS


@runtime_checkable
class ThreadStore(Protocol):
    """Async protocol for thread message stores.

    Implementations persist AG-UI messages keyed by ``thread_id``. Each message
    follows the AG-UI Message shape and may carry any combination of ``id``,
    ``role``, ``content``, ``toolCalls``, and ``toolCallId``.
    """

    async def get_messages(self, thread_id: str) -> list[dict[str, Any]]:
        """Return all stored messages for the given thread in insertion order."""
        ...

    async def append_message(self, thread_id: str, message: dict[str, Any]) -> None:
        """Append a single message, assigning an id if absent."""
        ...

    async def append_messages(
        self, thread_id: str, messages: list[dict[str, Any]]
    ) -> None:
        """Append multiple messages to the thread in order."""
        ...

    async def clear_thread(self, thread_id: str) -> None:
        """Remove all messages for a thread."""
        ...

    async def create_thread(self, user_id: str) -> ThreadInfo:
        """Mint a new thread id and register the thread under ``user_id``."""
        ...

    async def get_thread(self, thread_id: str) -> Optional[ThreadInfo]:
        """Return the thread's metadata, or ``None`` when it is unknown."""
        ...

    async def ensure_thread(self, thread_id: str, user_id: str) -> ThreadInfo:
        """Register a client-chosen thread id if missing and return its metadata.

        An existing thread keeps its owner; ``user_id`` only applies on insert.
        Appending messages never registers a thread, so callers claim one here.
        """
        ...

    async def list_threads(self, user_id: str) -> list[ThreadInfo]:
        """Return the threads owned by ``user_id``, newest activity first."""
        ...


class InMemoryThreadStore:
    """In-memory message store keyed by ``thread_id``.

    Intentionally simple — use :class:`SQLiteThreadStore` for history that
    survives a restart. Handy as a test double and as a default when no durable
    store is configured.
    """

    def __init__(self) -> None:
        self._store: dict[str, list[dict[str, Any]]] = defaultdict(list)
        self._threads: dict[str, ThreadInfo] = {}

    async def get_messages(self, thread_id: str) -> list[dict[str, Any]]:
        """Return a copy of all stored messages for the given thread."""
        return list(self._store[thread_id])

    async def append_message(self, thread_id: str, message: dict[str, Any]) -> None:
        """Append a single message to the thread, assigning an id if absent."""
        stored = _with_id(message)
        self._store[thread_id].append(stored)
        self._touch_thread(thread_id, [stored])

    async def append_messages(
        self, thread_id: str, messages: list[dict[str, Any]]
    ) -> None:
        """Append multiple messages to the thread in order."""
        for message in messages:
            await self.append_message(thread_id, message)

    async def clear_thread(self, thread_id: str) -> None:
        """Remove all messages for a thread."""
        self._store.pop(thread_id, None)

    async def create_thread(self, user_id: str) -> ThreadInfo:
        """Mint a new thread id and register the thread under ``user_id``."""
        thread = _new_thread(str(uuid.uuid4()), user_id)
        self._threads[thread.id] = thread
        return thread

    async def get_thread(self, thread_id: str) -> Optional[ThreadInfo]:
        """Return the thread's metadata, or ``None`` when it is unknown."""
        return self._threads.get(thread_id)

    async def ensure_thread(self, thread_id: str, user_id: str) -> ThreadInfo:
        """Register a client-chosen thread id if missing, keeping any owner."""
        existing = self._threads.get(thread_id)
        if existing is not None:
            return existing
        thread = _new_thread(thread_id, user_id)
        self._threads[thread_id] = thread
        return thread

    async def list_threads(self, user_id: str) -> list[ThreadInfo]:
        """Return the threads owned by ``user_id``, newest activity first."""
        owned = [t for t in self._threads.values() if t.user_id == user_id]
        return sorted(owned, key=lambda thread: thread.updated_at, reverse=True)

    def _touch_thread(self, thread_id: str, messages: list[dict[str, Any]]) -> None:
        """Bump ``updated_at`` and fill the title of an existing thread.

        A thread nobody registered stays unregistered: saving messages never
        creates one.
        """
        thread = self._threads.get(thread_id)
        if thread is None:
            return
        title = thread.title or _title_from_messages(messages)
        self._threads[thread_id] = thread.model_copy(
            update={"title": title, "updated_at": _now()}
        )


class SQLiteThreadStore:
    """SQLite-backed thread message store.

    Each AG-UI message is stored as a JSON blob in a single ``thread_messages``
    table, which preserves arbitrary fields (``toolCalls``, ``toolCallId``, ...)
    without schema migrations. All synchronous DB work runs via
    ``asyncio.to_thread`` so the event loop is never blocked.

    The store shares its database file with the v1 history store, so every
    connection opts into WAL mode plus conservative pragmas (``synchronous`` and
    ``busy_timeout``) to keep concurrent v1/v2 writers from colliding.
    """

    _TABLE = "thread_messages"
    _THREADS_TABLE = "copilot_threads"
    _BUSY_TIMEOUT_MS = 5000

    def __init__(self, db_path: str) -> None:
        # Fail fast on a missing/empty path: sqlite3.connect("") silently opens a
        # throwaway temp database and None raises an opaque TypeError deeper in,
        # so a misconfiguration would otherwise surface as "history vanished".
        if not db_path or not db_path.strip():
            raise ValueError(
                f"SQLiteThreadStore requires a non-empty database path; got "
                f"{db_path!r}."
            )
        self._db_path = db_path
        # A bare filename (no directory component) is valid — it resolves against
        # the cwd — so only create the parent directory when there is one.
        db_dir = os.path.dirname(db_path)
        if db_dir:
            os.makedirs(db_dir, exist_ok=True)
        self._init_db()

    def _init_db(self) -> None:
        with self._connection() as conn:
            conn.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {self._TABLE} (
                    id           INTEGER PRIMARY KEY AUTOINCREMENT,
                    thread_id    TEXT    NOT NULL,
                    message_id   TEXT    NOT NULL,
                    role         TEXT    NOT NULL,
                    message_json TEXT    NOT NULL,
                    created_at   REAL    NOT NULL
                )
                """
            )
            conn.execute(
                f"""
                CREATE INDEX IF NOT EXISTS idx_thread_time
                ON {self._TABLE}(thread_id, created_at, id)
                """
            )
            conn.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {self._THREADS_TABLE} (
                    id         TEXT PRIMARY KEY,
                    user_id    TEXT NOT NULL,
                    title      TEXT,
                    created_at REAL NOT NULL,
                    updated_at REAL NOT NULL
                )
                """
            )
            conn.execute(
                f"""
                CREATE INDEX IF NOT EXISTS idx_threads_user_updated
                ON {self._THREADS_TABLE}(user_id, updated_at)
                """
            )
            conn.commit()

    @contextmanager
    def _connection(self) -> Generator[sqlite3.Connection, None, None]:
        """Open a connection with WAL mode and the conservative shared pragmas.

        ``journal_mode`` is a persistent database-level setting; ``synchronous``
        and ``busy_timeout`` are per-connection and so are re-applied each time.
        """
        conn = sqlite3.connect(self._db_path, timeout=self._BUSY_TIMEOUT_MS / 1000)
        try:
            conn.execute("PRAGMA journal_mode=WAL")
            conn.execute("PRAGMA synchronous=NORMAL")
            conn.execute(f"PRAGMA busy_timeout={self._BUSY_TIMEOUT_MS}")
            yield conn
        finally:
            conn.close()

    def _read(self, thread_id: str) -> list[dict[str, Any]]:
        with self._connection() as conn:
            cursor = conn.execute(
                f"""
                SELECT message_json
                FROM {self._TABLE}
                WHERE thread_id = ?
                ORDER BY created_at, id
                """,
                (thread_id,),
            )
            return [json.loads(row[0]) for row in cursor.fetchall()]

    def _write(self, thread_id: str, message: dict[str, Any]) -> None:
        self._write_many(thread_id, [message])

    def _write_many(self, thread_id: str, messages: list[dict[str, Any]]) -> None:
        """Insert every message for a turn in a single transaction.

        Writing the whole turn atomically means a mid-turn failure rolls back the
        earlier rows too, so the store never holds a truncated turn that no longer
        matches what was streamed to the client.
        """
        stored = [_with_id(message) for message in messages]
        rows = [
            (
                thread_id,
                str(msg["id"]),
                str(msg.get("role", "")),
                json.dumps(msg, ensure_ascii=False),
                _now(),
            )
            for msg in stored
        ]
        with self._connection() as conn:
            try:
                conn.executemany(
                    f"""
                    INSERT INTO {self._TABLE}
                        (thread_id, message_id, role, message_json, created_at)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    rows,
                )
                self._touch_thread(conn, thread_id, _title_from_messages(stored))
                conn.commit()
            except Exception:
                conn.rollback()
                raise

    def _touch_thread(
        self, conn: sqlite3.Connection, thread_id: str, title: Optional[str]
    ) -> None:
        """Bump ``updated_at`` inside the caller's transaction.

        Only touches a thread that already has a row: saving messages never
        registers one. Fills the title once; a title that is already set is
        never overwritten.
        """
        conn.execute(
            f"""
            UPDATE {self._THREADS_TABLE}
            SET updated_at = ?, title = COALESCE(title, ?)
            WHERE id = ?
            """,
            (_now(), title, thread_id),
        )

    def _ensure_thread(self, thread_id: str, user_id: str) -> ThreadInfo:
        self._insert_thread(thread_id, user_id)
        thread = self._select_thread(thread_id)
        if thread is None:
            raise RuntimeError(f"Thread {thread_id} vanished right after creation.")
        return thread

    def _insert_thread(self, thread_id: str, user_id: str) -> None:
        now = _now()
        with self._connection() as conn:
            conn.execute(
                f"""
                INSERT OR IGNORE INTO {self._THREADS_TABLE}
                    (id, user_id, title, created_at, updated_at)
                VALUES (?, ?, NULL, ?, ?)
                """,
                (thread_id, user_id, now, now),
            )
            conn.commit()

    def _select_thread(self, thread_id: str) -> Optional[ThreadInfo]:
        with self._connection() as conn:
            row = conn.execute(
                f"""
                SELECT id, user_id, title, created_at, updated_at
                FROM {self._THREADS_TABLE}
                WHERE id = ?
                """,
                (thread_id,),
            ).fetchone()
        return _thread_from_row(row) if row is not None else None

    def _select_threads(self, user_id: str) -> list[ThreadInfo]:
        with self._connection() as conn:
            rows = conn.execute(
                f"""
                SELECT id, user_id, title, created_at, updated_at
                FROM {self._THREADS_TABLE}
                WHERE user_id = ?
                ORDER BY updated_at DESC
                """,
                (user_id,),
            ).fetchall()
        return [_thread_from_row(row) for row in rows]

    def _delete(self, thread_id: str) -> None:
        with self._connection() as conn:
            conn.execute(
                f"DELETE FROM {self._TABLE} WHERE thread_id = ?",
                (thread_id,),
            )
            conn.commit()

    def _handle_missing_table(self, exc: sqlite3.OperationalError) -> bool:
        """Recreate the table when a read/write hit a dropped/wiped database."""
        if "no such table" in str(exc).lower():
            self._init_db()
            return True
        return False

    async def get_messages(self, thread_id: str) -> list[dict[str, Any]]:
        """Return all stored messages for the given thread in insertion order."""
        try:
            return await asyncio.to_thread(self._read, thread_id)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                return []
            raise

    async def append_message(self, thread_id: str, message: dict[str, Any]) -> None:
        """Append a single message to the thread."""
        try:
            await asyncio.to_thread(self._write, thread_id, message)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                await asyncio.to_thread(self._write, thread_id, message)
                return
            raise

    async def append_messages(
        self, thread_id: str, messages: list[dict[str, Any]]
    ) -> None:
        """Append all messages for a turn atomically (single transaction)."""
        if not messages:
            return
        try:
            await asyncio.to_thread(self._write_many, thread_id, messages)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                await asyncio.to_thread(self._write_many, thread_id, messages)
                return
            raise

    async def clear_thread(self, thread_id: str) -> None:
        """Remove all messages for a thread."""
        try:
            await asyncio.to_thread(self._delete, thread_id)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                return
            raise

    async def create_thread(self, user_id: str) -> ThreadInfo:
        """Mint a new thread id and register the thread under ``user_id``."""
        return await self._run_recovering(
            self._ensure_thread, str(uuid.uuid4()), user_id
        )

    async def get_thread(self, thread_id: str) -> Optional[ThreadInfo]:
        """Return the thread's metadata, or ``None`` when it is unknown."""
        return await self._run_recovering(self._select_thread, thread_id)

    async def ensure_thread(self, thread_id: str, user_id: str) -> ThreadInfo:
        """Register a client-chosen thread id if missing, keeping any owner."""
        return await self._run_recovering(self._ensure_thread, thread_id, user_id)

    async def list_threads(self, user_id: str) -> list[ThreadInfo]:
        """Return the threads owned by ``user_id``, newest activity first."""
        return await self._run_recovering(self._select_threads, user_id)

    async def _run_recovering(self, func: Callable[..., _T], *args: Any) -> _T:
        """Run blocking DB work off the loop, retrying once after table recovery."""
        try:
            return await asyncio.to_thread(func, *args)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                return await asyncio.to_thread(func, *args)
            raise


def _new_thread(thread_id: str, user_id: str) -> ThreadInfo:
    """Return the metadata of a thread created now, still without a title."""
    now = _now()
    return ThreadInfo(
        id=thread_id, user_id=user_id, title=None, created_at=now, updated_at=now
    )


def _thread_from_row(row: tuple[Any, ...]) -> ThreadInfo:
    """Build thread metadata from a row selected in ``ThreadInfo`` field order."""
    thread_id, user_id, title, created_at, updated_at = row
    return ThreadInfo(
        id=thread_id,
        user_id=user_id,
        title=title,
        created_at=created_at,
        updated_at=updated_at,
    )


def _title_from_messages(messages: list[dict[str, Any]]) -> Optional[str]:
    """Return the title derived from the first non-blank user text, if any."""
    for message in messages:
        content = message.get("content")
        if message.get("role") == "user" and isinstance(content, str):
            title = title_from_text(content)
            if title is not None:
                return title
    return None


def _with_id(message: dict[str, Any]) -> dict[str, Any]:
    """Return a shallow copy of ``message`` with an ``id`` guaranteed to be set."""
    msg = dict(message)
    if not msg.get("id"):
        msg["id"] = uuid.uuid4().hex
    return msg
